/*******************************************************************//**
PURPOSE: Methods for SmTouchData objects

NOTES: The SmTouchData class is a I/O class used in the ClassifyLoop
       sequence
***********************************************************************/

/*******************************************************************//**
PURPOSE: TouchData compare - node only

NOTES: 1. Only this node is compared, not the descendants
       2. to use SmTArray<SmTouchData> must support operator==
***********************************************************************/
SmBoolean SmTouchData::operator==
 (const SmTouchData &crOther) 
 const  
{ SmBoolean bRtn = TRUE ;
  if(this == &crOther)
    { return bRtn ; }
  bRtn &= m_pConnectedTo    == crOther.m_pConnectedTo ;
  bRtn &= m_eLoopDir        == crOther.m_eLoopDir ; 
  bRtn &= m_lLoopIndx       == crOther.m_lLoopIndx ; 
  bRtn &= m_dParam          == crOther.m_dParam ;
  bRtn &= m_lPtClassifyIndx == crOther.m_lPtClassifyIndx ;
  bRtn &= m_pPtClassify     == crOther.m_pPtClassify ;
  return(bRtn) ;

} // end SmTouchData::operator==  - no recursion

/*******************************************************************//**
PURPOSE: combine a set of ordered SmTouchData lists into a single
         ordered list.
NOTES: Lists are in ascending ordered of List_Item::m_dParam values
***********************************************************************/
void SmTouchData::Homogenize
 (SmTArray< SmTArray<SmTouchData> > & rInLists,  // in : lists to combine, each ordered:[m_dParam]
  SmTArray<SmTouchData>             & rOutList)  // out: combined single list of all InList entries, ordered:[m_dParam]
{
  ULONG ii, jj, cnt = 0, lCount = 0;  // lNextList;
  SmTArray<ULONG> sIndx(rInLists.GetSize(), NULL, rInLists.GetSize()) ; 
  sIndx.SetAll(0) ;

  // get number of input touches
  for(ii=0;ii<rInLists.GetSize();ii++) { lCount += rInLists[ii].GetSize() ; }

  // init output
  rOutList.ReSet() ;
  rOutList.SetSize(lCount) ;

  // for every TouchData
  for(ii=0;ii<lCount;ii++)
    {
      SmTouchData * pNextData = NULL ;

      // for every sInList - find the next TouchData to add to OutList
      for(jj=0;jj<rInLists.GetSize();jj++)
        {
          // if Listjj has remaining members
          if(sIndx[jj] < rInLists[jj].GetSize())
            {
              // if 1st remaining member has the lowest m_dParam value
              if(   (pNextData == NULL) 
                 || (pNextData->m_dParam > rInLists[jj].GetAt(sIndx[jj]).m_dParam))
                {
                  // let candidate Next = this data
                  pNextData = &rInLists[jj].GetAt(sIndx[jj]) ;
                  // lNextList = jj ;
                } // end found a better candidate check
            } // end Listjj has remaining members check
        } // end iter jj - all InLists looking for the next ordered TouchData block
        
      // if we found a candidate
      if(pNextData)
        {
          // load output and increment indices
          rOutList[cnt] = *pNextData ; 
          cnt++ ;
          sIndx[jj]++ ;
        } // end Found a candidate check
    } // end iter every input TouchData element

  // check counts
  SM_ASSERT_MSG(lCount == cnt, _T("SmTouchData::Homogenize Sort Counts are off - a bug")) ;  

} // end SmTouchData::Homogenize

/*******************************************************************//**
PURPOSE: Build a TouchList of all touches connected to a given object
         out of a general Touchlist that might touch several objects

NOTES: CrossingCount = GetConnectedTouches().GetSize() / 2 
***********************************************************************/
ULONG SmTouchData::GetConnectedTouches
 (SmTopology            * pConnectedTo,      // in : ConnectedTo Tgt value
  SmTArray<SmTouchData> & rInTouchList,      // in : List of touches to review, ordered:[m_dParam]
  SmTArray<SmTouchData> * pOptOutTouchList)  // Out: Optional List of touches connected to Tgt, ordered:[m_dParam], 
                                             //      NULL to ignore, default:[NULL]
{
  // init output
  ULONG ii, lCnt=0 ;
  if(pOptOutTouchList)
    { pOptOutTouchList->SetSize(rInTouchList.GetSize()) ; // make sure m_lMaxSize is big enough
      pOptOutTouchList->ReSet() ;                         // set m_lSize == 0 to start
    }

  // for every touch
  for(ii=0;ii<rInTouchList.GetSize();ii++)
    {
      if(rInTouchList[ii].m_pConnectedTo == pConnectedTo)
        { lCnt++ ;
          if(pOptOutTouchList) pOptOutTouchList->Add(rInTouchList[ii]) ; 
        }
    }

  // all done
  return(lCnt) ;

} // end SmTouchData::GetConnectedTouches

/*******************************************************************//**
PURPOSE: Return WindingCount for given TouchList

NOTES: WindingCount = number of unmatched in/out out/in and out/in in/out
touches. A winding count only makes sense when all the touches in
the touch list are for a single loop. Use:
   Build a Curve on a Face:                     - to use as the ClassifyCrv
   SmCurveClassificaiton::SmCurveClassification - to build CrvClassification obj
   SmFace::CurveOnClassify()                    - to Classify the ClassifyCrv against the face
   SmCurveClassification::GetLoopCrossings()    - to get a TouchList for all Face::Loops
   SmTouchData::GetConnectedTouches()           - to get a TouchList for TgtLoop (CrossingCnt = TouchCnt / 2)
   SmTouchData::GetWindingCount()               - To count number of times TgtLoop winds about a periodic surface
WindingCount = number of unpaired In/Out and Out/In touches
WindingCount == 0 for all valid Area_Loops and for NoArea_Loops that wind in the same direction as the ClassifyCrv
WindingCount == 1 for NoArea_Loops winding in the direction orthogonal to the ClassifyCrv winding direction
WindingCount  > 1 (A spiral on a doubly periodic surface - think barber pole) a NoArea_Loop that breaks
                  up into a set of NoArea_Loops when the Loop is split into a set of Loops by splitting
                  the Loop at seam crossings.
Individual Bottom NoArea_Loops have to pair with individual Top NoArea_Loops to be healable.
***********************************************************************/
ULONG SmTouchData::GetWindingCount
 (SmTArray<SmTouchData> & rTouchList,   // in : single TgtLoop TouchList to review, ordered:[m_dParam]
  SmOrientType          & reOrientType) // out: oneof: SM_OT_UPPERDOMAIN = TouchList has unmatched Out/In Touches
                                        //             SM_OT_LOWERDOMAIN = TouchList has unmatched In/Out Touches
                                        //             SM_OT_UNKNOWN     = TouchList has no unmatched Out/In, InOut Touches
{
  // init locals and output
  ULONG ii, lInOutCnt=0, lOutInCnt=0 ;

  // for every touch
  for(ii=0;ii<rTouchList.GetSize();ii+=2)
    {
      if(   rTouchList[ii]  .m_eLoopDir == SM_CD_IN
         && rTouchList[ii+1].m_eLoopDir == SM_CD_OUT) { lInOutCnt++ ; }
      if(   rTouchList[ii]  .m_eLoopDir == SM_CD_OUT
         && rTouchList[ii+1].m_eLoopDir == SM_CD_IN)  { lOutInCnt++ ; }
    }

  // all done - return WindingCount = unpaired In/Out to Out/In touches
  reOrientType =   (lInOutCnt > lOutInCnt) ? SM_OT_LOWERDOMAIN
                 : (lInOutCnt < lOutInCnt) ? SM_OT_UPPERDOMAIN
                 : SM_OT_UNKNOWN ;

  return smos_Labs(lInOutCnt - lOutInCnt) ;                                   

} // end SmTouchData::GetWindingCount

/*******************************************************************//**
PURPOSE: pretty print one line for an arriving or departing TouchDir obj

NOTES: only ouputs values - no punctuation or line feeds 

bNoDetails == TRUE :  "LoopDirType" 
           == FALSE:  "LoopDirType(Param:[val] PtClassifyIndx:[val] PtClassifyPtr:[val])"

  where LoopDirType is OneOf: 
  'In', 'On', 'Out', 'Pole', 'Seam', 'Lamina', 'UnInit'
***********************************************************************/
void SmTouchData::Dump
 (SmBoolean bNoDetails)   // in : TRUE =output only the eLoopDir value
const                     //      FALSE=pretty print all values
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE] ;

  // header
  if(bNoDetails)
    {
      smos_sprintf(sBuff,_T("%s"),
                   m_eLoopDir == SM_CD_UNINIT          ? _T("UnInit")
                 : m_eLoopDir == SM_CD_IN              ? _T("In    ")
                 : m_eLoopDir == SM_CD_ON              ? _T("On    ")
                 : m_eLoopDir == SM_CD_OUT             ? _T("Out   ")
                 : m_eLoopDir == SM_CD_POLE            ? _T("Pole  ")
                 : m_eLoopDir == SM_CD_POLE_NO_VERTEX  ? _T("PoleNoVertex")
                 : m_eLoopDir == SM_CD_SEAM            ? _T("Seam  ")
                 : m_eLoopDir == SM_CD_LAMINA          ? _T("Lamina")
                 : _T("UnExpected")                    
                 ) ;
      SM_STRCPY(sBuffForFile, sBuff) ;

    } // end NoDetails branch
  else // with Details branch
    {
      smos_sprintf(sBuff,_T("%s (Param:[%8.8lf] ConnectedTo:[0x%p] LoopIndx:[%2lu] PtIndx:[%2lu] PtClassify:[0x%p])"),
                   m_eLoopDir == SM_CD_UNINIT          ? _T("UnInit")
                 : m_eLoopDir == SM_CD_IN              ? _T("In")
                 : m_eLoopDir == SM_CD_ON              ? _T("On")
                 : m_eLoopDir == SM_CD_OUT             ? _T("Out")
                 : m_eLoopDir == SM_CD_POLE            ? _T("Pole")
                 : m_eLoopDir == SM_CD_POLE_NO_VERTEX  ? _T("PoleNoVertex")
                 : m_eLoopDir == SM_CD_SEAM            ? _T("Seam")
                 : m_eLoopDir == SM_CD_LAMINA          ? _T("Lamina")
                 : _T("UnExpected"), 
                 m_dParam,
                 m_pConnectedTo,
                 m_lLoopIndx,
                 m_lPtClassifyIndx,
                 m_pPtClassify) ;
      smos_sprintf(sBuffForFile,_T("%s (Param:[%8.8lf] ConnectedTo:[%s] LoopIndx:[%2lu] PtIndx:[%2lu] PtClassify:[%s])"),
                                m_eLoopDir == SM_CD_UNINIT          ? _T("UnInit")
                              : m_eLoopDir == SM_CD_IN              ? _T("In")
                              : m_eLoopDir == SM_CD_ON              ? _T("On")
                              : m_eLoopDir == SM_CD_OUT             ? _T("Out")
                              : m_eLoopDir == SM_CD_POLE            ? _T("Pole") 
                              : m_eLoopDir == SM_CD_POLE_NO_VERTEX  ? _T("PoleNoVertex")
                              : m_eLoopDir == SM_CD_SEAM            ? _T("Seam")
                              : m_eLoopDir == SM_CD_LAMINA          ? _T("Lamina")
                              : _T("UnExpected"), 
                              m_dParam,
                              m_pConnectedTo == NULL ? _T("NULL") : _T("NotNULL"),
                              m_lLoopIndx,
                              m_lPtClassifyIndx,
                              m_pPtClassify == NULL ? _T("NULL") : _T("NotNULL")) ;
    } // end IsArrival check

  // inform the public
  smos_WriteBuffer(sBuff, sBuffForFile);

} // end SmTouchData::Dump

/*******************************************************************//**
PURPOSE: pretty print TouchList Array

NOTES: 

bNoDetails == TRUE :  "Label TouchList [ArriveType/DepartType ArriveType/DepartType ...]"
           == FALSE:  "Begin Label TouchList
                         [ 0] ArriveType(Param:[val] PtClassifyIndx:[val] PtClassifyPtr:[val])
                              DepartType(Param:[val] PtClassifyIndx:[val] PtClassifyPtr:[val])
                         [ 1] ArriveType(Param:[val] PtClassifyIndx:[val] PtClassifyPtr:[val])
                         ...
                       End Label TouchList"

  where LoopDirType is OneOf: 
  'In', 'On', 'Out', 'Pole', 'Seam', 'Lamina', 'UnInit'
***********************************************************************/
void SmTouchData::DumpTouchList
 (const TCHAR                 * pLabel,      // in : string included in output header
  const SmTArray<SmTouchData> & rTouchList,  // in : Touch list as :[ArriveTouchDir_0 DepartTouchDir_0, ArriveTouchDir_1 ...]
  SmBoolean                     bNoDetails)  // in : TRUE =output only a string of eLoopDir values on one line
                                             //      FALSE=output one eLoopDir with all its associated data values per line
                                             //      default:[TRUE]
{
  ULONG lCnt = 0 ;
  TCHAR sBuff[SM_TBLOCK_SIZE] ;

  // header
  if(bNoDetails) { smos_sprintf(sBuff,_T("\n     %s TouchList ["), pLabel) ; }
  else           { smos_sprintf(sBuff,_T("\n     Begin %s TouchList"), pLabel) ; }
  smos_WriteBuffer(sBuff) ;

  // special case - empty touch list
  if(rTouchList.GetSize() == 0)
    { 
      if(bNoDetails==FALSE) { smos_WriteBuffer(_T("\n  ")) ; }
      smos_WriteBuffer(_T("Empty List - No Touches")) ;  
    }

  // list
  for(ULONG ii=0;ii<rTouchList.GetSize();ii+=2,lCnt=0)
    {
      // arrival intro
      if(bNoDetails == FALSE)
        { smos_sprintf(sBuff, _T("\n  [%2ld-Arr] "), ii/2) ; }
      else
        { smos_sprintf(sBuff,_T("Loop:[0x%p]:"),rTouchList[ii].m_pConnectedTo) ; }
      smos_WriteBuffer(sBuff) ;

      // arriving TouchDir
      rTouchList[ii].Dump(bNoDetails) ; 
      lCnt +=      rTouchList[ii].m_eLoopDir == SM_CD_UNINIT           ? 6
                 : rTouchList[ii].m_eLoopDir == SM_CD_NONE             ? 4
                 : rTouchList[ii].m_eLoopDir == SM_CD_IN               ? 2
                 : rTouchList[ii].m_eLoopDir == SM_CD_ON               ? 2
                 : rTouchList[ii].m_eLoopDir == SM_CD_OUT              ? 3
                 : rTouchList[ii].m_eLoopDir == SM_CD_LAMINA           ? 6
                 : rTouchList[ii].m_eLoopDir == SM_CD_SEAM             ? 4
                 : rTouchList[ii].m_eLoopDir == SM_CD_POLE             ? 4
                 : rTouchList[ii].m_eLoopDir == SM_CD_POLE_NO_VERTEX   ? 14
                 :                                                       6 ;


      // Arrival/Departure separator
      if(bNoDetails) { smos_WriteBuffer(_T("/")) ; }
      else           { smos_WriteBuffer(_T("\n     -Dep] ")) ; }

      // departing TouchDir
      rTouchList[ii+1].Dump(bNoDetails) ;
      lCnt +=      rTouchList[ii+1].m_eLoopDir == SM_CD_UNINIT         ? 6
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_NONE           ? 4
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_IN             ? 2
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_ON             ? 2
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_OUT            ? 3
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_LAMINA         ? 6
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_SEAM           ? 4
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_POLE           ? 4
                 : rTouchList[ii+1].m_eLoopDir == SM_CD_POLE_NO_VERTEX ? 14
                 :                                                       6 ;

      // departure ending
      if(   bNoDetails 
         && ii < rTouchList.GetSize()-2) 
        { for(ULONG di=0;di<13-lCnt;di++) smos_WriteBuffer(_T(" ")) ; }
    } // end iter every arrival/departure touch list pair

  // footer
  if(bNoDetails) { smos_sprintf(sBuff, _T("%s"), _T("]")) ; }
  else           { smos_sprintf(sBuff, _T("\n     End %s TouchList"), pLabel) ; }
  smos_WriteBuffer(sBuff) ;

} // end SmTouchData::DumpTouchList

