/*******************************************************************//**
PURPOSE:

RETURNS ---  TRUE  = OK
             FALSE = Problem
**********************************************************************/
SmBoolean SmCurveClassification::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL]
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests,
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests
                                    //      default:[SM_LEVEL_0]
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK]
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  // init rtn value
  SmBoolean bRtn  = TRUE ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmObject::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests)
           : TRUE ) ;

  // no work - UnInit object
  SmBoolean bUnInit = IsUnInit() ;
  if(bUnInit == TRUE)
    { return(bRtn) ; }

  // check simple members
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (m_cpCurve != NULL), _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, (m_bIsCurveCurrent == 0 || m_bIsCurveCurrent == 1), _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (m_lMaxSize >= m_lSize), _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, (m_lSize == 0 || m_pData != NULL), _T("") ) ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, (m_bIgnoreTangency == 0 || m_bIgnoreTangency == 1), _T("") ) ;

  // check consistency of interval boundaries
  if(m_lSize > 0)
    {
      // Interval bounds consistent with Classification bounds
      bRtn &= SM_ASSERT_VALUE_REPORT(5, SM_LEVEL_0, (SM_ARE_SAME_TO_TOL(m_vInterval.GetMin(),m_pData[0].m_vInterval.GetMin(), SM_EFF_ZERO)), SM_EFF_ZERO, m_vInterval.GetMin()-m_pData[0].m_vInterval.GetMin(), _T("") );
      bRtn &= SM_ASSERT_VALUE_REPORT(6, SM_LEVEL_0, (SM_ARE_SAME_TO_TOL(m_vInterval.GetMax(),m_pData[m_lSize-1].m_vInterval.GetMax(),SM_EFF_ZERO)), SM_EFF_ZERO,m_vInterval.GetMax()-m_pData[m_lSize-1].m_vInterval.GetMax(), _T("") );

      // interval bounds consistent with one another
      for(ULONG ii=0, i1=1; i1<m_lSize;ii++, i1++)
        {
          bRtn &= SM_ASSERT_VALUE_REPORT(7, SM_LEVEL_0, (SM_ARE_SAME_TO_TOL(m_pData[ii].m_vInterval.GetMax(),m_pData[i1].m_vInterval.GetMin(), SM_EFF_ZERO)), SM_EFF_ZERO, m_pData[ii].m_vInterval.GetMax()-m_pData[i1].m_vInterval.GetMin(), _T("") );
        }
    } // end have classification intervals to test check

  // 8 - When DoingFillet, m_cpOtherClassification must be nonNULL
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(8, SM_LEVEL_0, (m_bDoingFillets == FALSE || (m_cpOtherClassification != NULL)), _T("") ) ;

  // 9 - m_bTgtLoopsOnly must be 0 or 1
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(9, SM_LEVEL_0, (m_bTgtLoopsOnly == FALSE || m_bTgtLoopsOnly == TRUE), _T("") ) ;

  // 10 - m_pOnlyLoop ptr Must be NULL or a member Loop of m_cpFace
  if(m_bTgtLoopsOnly && m_cpFace)
    {
      ULONG ii ; 
      SmTArray<SmLoop*> sLoops ;
      SmBoolean bIsIn = TRUE ; 
      m_cpFace->GetLoops(sLoops) ;
      for(ii=0;ii<m_sTgtLoops.GetSize();ii++)
        {
          bIsIn &= m_cpFace == m_sTgtLoops[ii]->GetFace() ; 
        }
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(10, SM_LEVEL_0, (   m_bTgtLoopsOnly == FALSE 
                                                        || m_cpFace        == NULL 
                                                        || bIsIn           == TRUE), 
                                                       _T("") ) ;
    } // end need to run Assert 10 check

  // 11 - m_bOKToSetTolerance must be 0 or 1
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(9, SM_LEVEL_0, (m_bOKToSetTolerance == FALSE || m_bOKToSetTolerance == TRUE), _T("") ) ;

  // Check contained CurveIntervals
  for(ULONG ii=0;ii<GetSize();ii++)
    {
      SmCurveInterval & rCurveInterval = GetAt(ii) ;
      bRtn &= rCurveInterval.AssertValid(pAList, eTestLevel, eWalkTree, pTestRequests) ; 
    }

  // all done
  // SM_ASSERT(bRtn) ;
  return(bRtn) ;

} // end SmCurveClassification::AssertValid

