/*******************************************************************//****
PURPOSE:

NOTES:
*************************************************************************/
void SmCurveClassification::Dump() const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE] ;

  // This can never be NULL
  //SM_ASSERT_MSG(this != 0x0, _T("SmCurveClassification::Dump called on a NULL ptr - should never happen")) ;

  // low work - SmCurveClassification is UnInit, ie. internal values are defaulted to UnSet values
  if(IsUnInit())
    {
      smos_sprintf(sBuff,       _T("\nSmCurveClassification:[0x%p] is UnInit:[Mem Allocated; Member Vals UnSet]"), this);
      smos_sprintf(sBuffForFile,_T("%s"), _T("\nSmCurveClassification:[NotNULL] is UnInit:[Mem Allocated; Member Vals UnSet]")) ; 
      smos_WriteBuffer(sBuff, sBuffForFile);
      return ;

    } // end low work - CurvClassification is UnInit

  SmZoneTol3d sSrcZoneTol3d = SmTol::GetSrcZoneTol3d(this) ;

  smos_sprintf(sBuff,_T("\nSmCurveClassification:[0x%p] #Ivls:[%ld] Interval:[%16.16lf, %16.16lf] cpCurve:[0x%p%s] Tol:[%16.16lg] AllocSize:[%ld] bIsBorrowed:[%s] "),
             this,
             m_lSize,
             m_vInterval.GetMin(),
             m_vInterval.GetMax(),
             m_cpCurve,
               m_cpCurve &&  m_bIsCurveOwned ? _T(" Owned") 
             : m_cpCurve && !m_bIsCurveOwned ? _T(" NotOwned") : _T(""),
             (double) sSrcZoneTol3d,
             m_lMaxSize,
             m_bIsBorrowed ? _T("TRUE") : _T("FALSE"));
  smos_sprintf(sBuffForFile,_T("\nSmCurveClassification #Ivls:[%ld] Interval:[%16.16lf, %16.16lf] cpCurve:[%s] Tol:[%16.16lg] AllocSize:[%ld] bIsBorrowed:[%s]"),
             m_lSize,
             m_vInterval.GetMin(),
             m_vInterval.GetMax(),
               m_cpCurve &&  m_bIsCurveOwned ? _T("NotNULL - Owned") 
             : m_cpCurve && !m_bIsCurveOwned ? _T("NotNULL - NotOwned") : _T("NULL"),
             (double) sSrcZoneTol3d,
             m_lMaxSize,
             m_bIsBorrowed ? _T("TRUE") : _T("FALSE"));
  smos_WriteBuffer(sBuff, sBuffForFile);

  smos_sprintf(sBuff,_T("\n           XSectData:  Face:[0x%p] Srf1:[0x%p] Srf2:[0x%p] UVCrv1:[0x%p], UVCrv2:[0x%p]"),
             m_cpFace,      
             m_cpSurface1,
             m_cpSurface2,
             m_cpUVCurve1,
             m_cpUVCurve2);
  smos_sprintf(sBuffForFile,_T("\n           XSectData:  Face:[%s] Srf1:[%s] Srf2:[%s] UVCrv1:[%s], UVCrv2:[%s]"),
             m_cpFace     ? _T("NotNULL") : _T("NULL"),
             m_cpSurface1 ? _T("NotNULL") : _T("NULL"),
             m_cpSurface2 ? _T("NotNULL") : _T("NULL"),
             m_cpUVCurve1 ? _T("NotNULL") : _T("NULL"),
             m_cpUVCurve2 ? _T("NotNULL") : _T("NULL"));

  smos_WriteBuffer(sBuff, sBuffForFile);
                               
  smos_sprintf(sBuff,_T("\n      CrossHatchData:  DoingCrossHatch:[%s]"),
             m_bDoingCrossHatch ? _T("TRUE") : _T("FALSE") ) ;
  smos_WriteBuffer(sBuff);
                       
  smos_sprintf(sBuff,_T("\n          FilletData:  DoingFillets:[%s] OtherClassification:[0x%p]"),
             m_bDoingFillets ? _T("TRUE") : _T("FALSE"),
             m_cpOtherClassification);
  smos_sprintf(sBuffForFile,_T("\n          FilletData:  DoingFillets:[%s] OtherClassification:[%s]"),
             m_bDoingFillets ? _T("TRUE") : _T("FALSE"),
             m_cpOtherClassification ? _T("NotNULL") : _T("NULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);
                       
  smos_sprintf(sBuff,_T("\n    LoopClassifyData:  Use TgtLoopsOnly:[%s] TgtLoopCnt:[%lu] (TRUE && 0= Use OuterLoop as only TgtLoop)"),
             m_bTgtLoopsOnly ? _T("TRUE") : _T("FALSE"),
             m_sTgtLoops.GetSize());
  smos_WriteBuffer(sBuff);

  smos_sprintf(sBuff,_T("\n           OtherData:  bOKToSetTolerance:[%s] bIgnoreTangency:[%s] bIsCurveCurrent:[%s] TopoXSector:[0x%p]"),
             m_bOKToSetTolerance ? _T("TRUE") : _T("FALSE"),
             m_bIgnoreTangency ? _T("TRUE") : _T("FALSE"),
             m_bIsCurveCurrent ? _T("TRUE") : _T("FALSE"),
             m_cpTI);
  smos_sprintf(sBuffForFile,_T("\n           OtherData:  bOKToSetTolerance:[%s] bIgnoreTangency:[%s] bIsCurveCurrent:[%s] TopoXSector:[%s]"),
             m_bOKToSetTolerance ? _T("TRUE") : _T("FALSE"),
             m_bIgnoreTangency ? _T("TRUE") : _T("FALSE"),
             m_bIsCurveCurrent ? _T("TRUE") : _T("FALSE"),
             m_cpTI ? _T("NotNULL") : _T("NULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

  SmObject::Dump();

  // interval summary
  if(0 == m_lSize)
    {
      smos_sprintf(sBuff,_T("%s"), _T("   NO intervals in CurveClassification\n")) ;
      smos_WriteBuffer(sBuff);
    }

  for (ULONG i = 0; i < m_lSize; i++)
    {
      smos_sprintf(sBuff,_T("   [%ld] - "),i);
      smos_WriteBuffer(sBuff);

      SmPoint3d sStartPoint = GetClassifyCrvLoc(i) ;
      SmPoint3d sEndPoint   = GetClassifyCrvLoc(i+1) ;
      m_pData[i].Dump(GetCurve()->GetDim(), &sStartPoint, &sEndPoint, GetSurface1(), GetSurface2());
    }

} // end SmCurveClassification::Dump

/*******************************************************************//****
PURPOSE: Draw classification curve and interval point boundaries (cyan).

NOTES:
*************************************************************************/
SmDisplayList * SmCurveClassification::Draw
  (SmBoolean bDrawObjects)   // in : TRUE = Draw CurveIvl classification objs, FALSE = Don't
                             //      default:[TRUE]
 const
{
  SmDisplayList *pRtn = NULL ;

  // no work - empty CurvClassification
  if(NULL == GetCurve())
    { return(pRtn) ; }

#ifdef SM_GFX_CODE
  // start or continue using currently open display list
  smgfx_Open(smgfx_GetRuleColor(this));

  // draw curve being classified
  // m_cpCurve->Draw(0);
  ULONG ii ;
  SmVector3d      sColor   = smgfx_GetColor() ;
  const SmCurve * pCurve   = m_cpCurve ;
  SmSurface     * pSurface = NULL ;

  // Check for UVTrimCurves - set pSurface != NULL
  if (m_cpCurve->GetDim() == 2)
    {
      // Try and find the UVTrimCurve's Surface
      pSurface =   (m_cpCurve->GetOwner() && m_cpCurve->GetOwner()->IsKindOf(SmSurface_TYPE)) ? (SmSurface *)m_cpCurve->GetOwner()
                 : (m_cpCurve->GetOwner() && m_cpCurve->GetOwner()->IsKindOf(SmFace_TYPE)) ? ((SmFace *)m_cpCurve->GetOwner())->GetSurface()
                 : (m_cpSurface1 != NULL) ? (SmSurface *)m_cpSurface1
                 : NULL ;
    }

  // for every interval - draw min and max points and classify vertex/edge objects
  for(ii=0;ii<m_lSize;ii++)
    {
      // draw interval min/max points in cyan
      // draw curve interval - nice in debug mode - one can step through and figure
      //                       out which interval is which

      // SmVector3d sColor = smgfx_OutputColor(0,1,1);
      smgfx_ChangeColor(ii!=0) ;
      if(pSurface)
        {
          SmCrvOnSurf sCrvOnSurf((SmCurve &)*pCurve, *pSurface) ;
          sCrvOnSurf.DrawAt(m_pData[ii].m_vInterval.GetMin(),0);
          sCrvOnSurf.DrawAt(m_pData[ii].m_vInterval.GetMax(),0);
          sCrvOnSurf.Draw(&m_pData[ii].m_vInterval) ;
        }
      else // working with a 3d curve
        {
          m_cpCurve->DrawAt(m_pData[ii].m_vInterval.GetMin(),0);
          m_cpCurve->DrawAt(m_pData[ii].m_vInterval.GetMax(),0);
          m_cpCurve->Draw(&m_pData[ii].m_vInterval) ;
        }

      // smgfx_OutputColor(sColor);

      // draw objects to which interval classifies
      if(bDrawObjects)
        { m_pData[ii].Draw(); }
    } // end iter ii - every interval

  // Draw ClassifyCrv with params
  double dLineWidth = smgfx_SetLineWidth(1) ;
  if(pSurface)
    {
      SmCrvOnSurf sCrvOnSurf((SmCurve &)*pCurve, *pSurface) ;
      sCrvOnSurf.DrawParams() ;
    }
  else  // working with a 3d curve
    {
      m_cpCurve->DrawParams() ;
    }
  smgfx_SetLineWidth(dLineWidth) ;

  // all done
  smgfx_SetColor(sColor) ;
  pRtn = smgfx_Close() ;

#else
  SM_REF1(bDrawObjects);
#endif // SM_GFX_CODE

  return(pRtn) ;

} // end SmCurveClassification::Draw()

/*******************************************************************//****
PURPOSE:  For each interval, draw curve and endPoints plus the object
        to which they classify.

NOTES: Set object vertex, edge, and face size and colors with
  smgfx_SetCurveClassificationObjectLook() ;
*************************************************************************/
SmDisplayList * SmCurveClassification::DrawObjects()
 const
{
  SmDisplayList *pRtn = NULL ;

#ifdef SM_GFX_CODE
  // start or continue using currently open display list
  smgfx_Open(smgfx_GetRuleColor(this));

  double     dLineWidth = smgfx_GetLineWidth() ;
  double     dPointSize = smgfx_GetPointSize() ;
  SmVector3d sInColor   = smgfx_GetOutputColor() ;
  SmVector3d sColor     = sInColor ;
  if(sColor.IsUndef() || sColor.x == SM_BIG_DOUBLE) { sColor.Set(1,0,0) ; }
  SmVector3d sVertexColor, sEdgeColor, sFaceColor ;
  smgfx_GetCurveClassificationObjectColors(sVertexColor, sEdgeColor, sFaceColor) ;
  //double dVScale = smos_Sqrt(sVertexColor.LengthSquared() - 2*sVertexColor.x - 2*sVertexColor.y - 2*sVertexColor.z + 3) ;
  //double dEScale = smos_Sqrt(sEdgeColor.LengthSquared()   - 2*sEdgeColor.x   - 2*sEdgeColor.y   - 2*sEdgeColor.z   + 3) ;
  //double dFScale = smos_Sqrt(sFaceColor.LengthSquared()   - 2*sFaceColor.x   - 2*sFaceColor.y   - 2*sFaceColor.z   + 3) ;
  SmVector3d sVertexCompliment(smos_Min((1.0 - sVertexColor.x),1.0), smos_Min((1.0 - sVertexColor.y),1.0), smos_Min((1.0 - sVertexColor.z),1.0)) ;
  SmVector3d sEdgeCompliment  (smos_Min((1.0 - sEdgeColor.x),1.0)  , smos_Min((1.0 - sEdgeColor.y),1.0)  , smos_Min((1.0 - sEdgeColor.z),1.0)  ) ;
  SmVector3d sFaceCompliment  (smos_Min((1.0 - sFaceColor.x),1.0)  , smos_Min((1.0 - sFaceColor.y),1.0)  , smos_Min((1.0 - sFaceColor.z),1.0)  ) ;

  // for every interval
  for (ULONG i = 0; i < m_lSize; i++)
    {
      // set interval curve draw appearance
      SmPointClassificationType eMidType = m_pData[i].m_vMid.GetPointClass() ;
      SmVector3d sIntervalColor =   eMidType == SM_PC_VERTEX ? sVertexCompliment
                                  : eMidType == SM_PC_EDGE   ? sEdgeCompliment
                                  : eMidType == SM_PC_FACE   ? sFaceCompliment
                                  : sColor ;
      smgfx_OutputColor(sIntervalColor) ;
      smgfx_OutputLineWidth(dLineWidth) ;

      // draw interval curve
      m_cpCurve->Draw(&m_pData[i].m_vInterval);

      // draw endPoints
      smgfx_SetPointSize(dPointSize) ;
      smgfx_OutputColor(sVertexCompliment) ;
      m_cpCurve->DrawAt(m_pData[i].m_vInterval.GetMin(),0);
      m_cpCurve->DrawAt(m_pData[i].m_vInterval.GetMax(),0);

      // draw startInterval attachments
      if (m_pData[i].m_vStart.GetPointClass() == SM_PC_VERTEX)
        {
          smgfx_OutputColor(sVertexColor) ;
          smgfx_OutputPointSize(dPointSize + 3) ;
          SmVertex *pV = (SmVertex*)m_pData[i].m_vStart.GetObject();
          pV->Draw();
        }
      else if (m_pData[i].m_vStart.GetPointClass() == SM_PC_EDGE)
        {
          smgfx_OutputColor(sEdgeColor) ;
          smgfx_OutputLineWidth(dLineWidth + 2) ;
          SmEdge *pE = (SmEdge*)m_pData[i].m_vStart.GetObject();
          pE->Draw();
        }
      else if (m_pData[i].m_vStart.GetPointClass() == SM_PC_FACE)
        {
          smgfx_OutputColor(sFaceColor) ;
          smgfx_OutputLineWidth(1) ;
          smgfx_OutputPointSize(2) ;
          SmFace *pF = (SmFace*)m_pData[i].m_vStart.GetObject();
          pF->Draw(SM_DM_CROSSHATCH,12,12);
        }

      // draw midInterval attachments
      if (m_pData[i].m_vMid.GetPointClass() == SM_PC_VERTEX)
        {
          smgfx_OutputColor(sVertexColor) ;
          smgfx_OutputPointSize(dPointSize + 3) ;
          SmVertex *pV = (SmVertex*)m_pData[i].m_vMid.GetObject();
          pV->Draw();
        }
      else if (m_pData[i].m_vMid.GetPointClass() == SM_PC_EDGE)
        {
          smgfx_OutputColor(sEdgeColor) ;
          smgfx_OutputLineWidth(dLineWidth + 2) ;
          SmEdge *pE = (SmEdge*)m_pData[i].m_vMid.GetObject();
          pE->Draw();
        }
      else if (m_pData[i].m_vMid.GetPointClass() == SM_PC_FACE)
        {
          smgfx_OutputColor(sFaceColor) ;
          smgfx_OutputLineWidth(1) ;
          smgfx_OutputPointSize(2) ;
          SmFace *pF = (SmFace*)m_pData[i].m_vMid.GetObject();
          pF->Draw(SM_DM_CROSSHATCH,12,12);
        }

      // draw endInterval attachments
      if (m_pData[i].m_vEnd.GetPointClass() == SM_PC_VERTEX)
        {
          smgfx_OutputColor(sVertexColor) ;
          smgfx_OutputPointSize(dPointSize + 3) ;
          SmVertex *pV = (SmVertex*)m_pData[i].m_vEnd.GetObject();
          pV->Draw();
        }
      else if (m_pData[i].m_vEnd.GetPointClass() == SM_PC_EDGE)
        {
          smgfx_OutputColor(sEdgeColor) ;
          smgfx_OutputLineWidth(dLineWidth + 2) ;
          SmEdge *pE = (SmEdge*)m_pData[i].m_vEnd.GetObject();
          pE->Draw();
        }
      else if (m_pData[i].m_vEnd.GetPointClass() == SM_PC_FACE)
        {
          smgfx_OutputColor(sFaceColor) ;
          smgfx_OutputLineWidth(1) ;
          smgfx_OutputPointSize(2) ;
          SmFace *pF = (SmFace*)m_pData[i].m_vEnd.GetObject();
          pF->Draw(SM_DM_CROSSHATCH,12,12);
        }
    } // end iter every interval

  // restore state
  smgfx_OutputColor(sInColor) ;
  smgfx_OutputPointSize(dPointSize) ;
  smgfx_OutputLineWidth(dLineWidth) ;

  // all done
  pRtn = smgfx_Close() ;

#endif // SM_GFX_CODE
  return(pRtn) ;

} // end SmCurveClassification::DrawObjects

