/*******************************************************************//**
PURPOSE:  Get the curve being classified.

NOTES:
***********************************************************************/
const SmCurve * SmCurveInterval::GetCurve() const
{ return m_pCurveClassification->GetCurve() ; }

/*******************************************************************//**
PURPOSE:  Check Interval classifications for an object
  connected to a Brep and return that Brep

NOTES:
***********************************************************************/
SmBrep * SmCurveInterval::GetBrep
  (SmBrep *pSkipBrep)             // in : only return Breps which are not the given Brep,
                                  //      NULL to ignore, default:[NULL]
 const
{
  SmBrep *pBrep = NULL ;

  // check three classifications for objects connected to Breps
  pBrep                   = m_vStart.GetBrep(pSkipBrep) ;
  if(pBrep == NULL) pBrep = m_vMid.GetBrep(pSkipBrep) ;
  if(pBrep == NULL) pBrep = m_vEnd.GetBrep(pSkipBrep) ;

  // all done
  return(pBrep) ;

} // end SmCurveInterval::GetBrep

/*******************************************************************//****
PURPOSE: Get ClassifyInterval_MinPt projected to CrvClassification->Face->Surface

NOTES: When CrvClassification ClassifyCrv is 2d or a 3d CrvOnSurf, 
         evaluate ClassifyCrv to find return UV value 
       else when ClassifyCrv is 3d, Drop ClassifyCrv Evaluate Pt to Surface
         to find return UV value.

NOTES: returns SM_ERR when CrvClassification m_cpFace->pSurface == NULL
                           or the DropPoint() call fails
       else returns SM_SUCCESS
*************************************************************************/
SmStatus SmCurveInterval::GetMinUV
   (SmPoint2d &rUV)   // out: Interval Min position of associated
   const 
  { 
    // rtn value
    SmStatus sRtn = SM_SUCCESS ; 

    // locals
    SmPoint3d sUV3d ; 
    const SmCurve * pCurve = m_pCurveClassification->GetCurve() ;
    
    // set output - UV point
    if(pCurve->GetDim() == 2)                   
      { pCurve->EvaluatePoint(m_vInterval.GetMin(), sUV3d) ; 
        rUV = sUV3d ;
      } // end Curve is 2d branch

    else if(pCurve->IsKindOf(SmCrvOnSurf_TYPE)) 
      { ((SmCrvOnSurf *)pCurve)->EvaluateUVPoint(m_vInterval.GetMin(), rUV) ; 
      } // end Curve is CrvOnSurf_TYPE branch

    else // Curve is 3d branch - Use drop point - this needs something for dropping to Seams                                     
      { SmCurveClassification * pCrvClassification = GetCurveClassification() ;
        const SmFace          * pFace              = pCrvClassification ? pCrvClassification->GetFace() : NULL ; 
        const SmSurface       * pSurface           = pFace ? pFace->GetSurface() : NULL ;

        // check state - pCurve must be a 2d or a CrvOnSurf curve
        AERN_MSG(   (pCurve   != NULL)
                 && (pSurface != NULL),
                 SM_ERR,
                 _T("SmCurveInterval::GetMinUV - attempt to Get ClassifyInterval_SurfUVMin failed because Surface ptr is NULL")) ; 

        SmBoolean  bSuccess ;
        double     dGap ;
        SmBoolean bIsMulti ;
        SmVector3d sPoint3d ;
        pCurve->EvaluatePoint(m_vInterval.GetMin(), sPoint3d) ;
        sRtn = pSurface->DropPoint(sPoint3d, pSurface->GetNaturalUVDomain(), NULL, bSuccess, rUV, dGap, bIsMulti) ; 
      } // end Curve is 3d branch

    // all done
    return(sRtn) ;

  } // end SmCurveInterval::GetMinUV

/*******************************************************************//****
PURPOSE: Get ClassifyInterval_MaxPt projected to CrvClassification->Face->Surface

NOTES: When CrvClassification ClassifyCrv is 2d or a 3d CrvOnSurf, 
         evaluate ClassifyCrv to find return UV value 
       else when ClassifyCrv is 3d, Drop ClassifyCrv Evaluate Pt to Surface
         to find return UV value.

NOTES: returns SM_ERR when CrvClassification m_cpFace->pSurface == NULL
                           or the DropPoint() call fails
       else returns SM_SUCCESS
*************************************************************************/
SmStatus SmCurveInterval::GetMaxUV
   (SmPoint2d &rUV)   // out: Interval Max position of associated interval end
   const 
  { 
    // rtn value
    SmStatus sRtn = SM_SUCCESS ; 

    // locals
    SmPoint3d sUV3d ; 
    const SmCurve * pCurve = m_pCurveClassification->GetCurve() ;
    
    // set output - UV point
    if(pCurve->GetDim() == 2)                   
      { pCurve->EvaluatePoint(m_vInterval.GetMax(), sUV3d) ; 
        rUV = sUV3d ;
      } // end Curve is 2d branch

    else if(pCurve->IsKindOf(SmCrvOnSurf_TYPE)) 
      { ((SmCrvOnSurf *)pCurve)->EvaluateUVPoint(m_vInterval.GetMax(), rUV) ; 
      } // end Curve is CrvOnSurf_TYPE branch

    else // Curve is 3d branch - Use drop point - this needs something for dropping to Seams                                     
      { SmCurveClassification * pCrvClassification = GetCurveClassification() ;
        const SmFace          * pFace              = pCrvClassification ? pCrvClassification->GetFace() : NULL ; 
        const SmSurface       * pSurface           = pFace ? pFace->GetSurface() : NULL ;

        // check state - pCurve must be a 2d or a CrvOnSurf curve
        AERN_MSG(   (pCurve   != NULL)
                 && (pSurface != NULL),
                 SM_ERR,
                 _T("SmCurveInterval::GetMinUV - attempt to Get ClassifyInterval_SurfUVMin failed because Surface ptr is NULL")) ; 

        SmBoolean  bSuccess ;
        double     dGap ;
        SmBoolean bIsMulti;
        SmVector3d sPoint3d ;
        pCurve->EvaluatePoint(m_vInterval.GetMax(), sPoint3d) ;
        sRtn = pSurface->DropPoint(
            sPoint3d, pSurface->GetNaturalUVDomain(), NULL, bSuccess, rUV, dGap, bIsMulti); 
      } // end Curve is 3d branch

    // all done
    return(sRtn) ;

  } // end SmCurveInterval::GetMaxUV

/*******************************************************************//****
PURPOSE: When IvlEnd classifies to Face->Edge at a crossing intersection, 
           return EdgeObj->Edgeuse Bounding this ClassifyIvl, 
           else return NULL = NoEdgeuse boundary.                                                    

ToDo: This method needs to be extended to properly handle the case of a
ClassifyCrv coincident with CrvClassification EndPt->EdgeObj.  It only works
when that Edge is not coincident - that's ok to support the sms_ReviewStartAndStopOnSeamCrvClassifies()
function for which it was written - but it's not ready for general use in all parts of SMLib.
There's a block of obsolete code following sms_ReviewStartAndStopOnSeamCrvClassifies() that 
can be used to write this needed extension.  No Time to do that now - have to get the
1st healer release out the door.

NOTES: Returns NULL when the  
   1. CrvClassification is not being executed on a Face (m_cpFace == NULL)
   2. CrvClassification's m_cpFace has no Surface (not expected)
   3. CrvClassification EndPt does not classify to an Edge (m_vEndPt->PointClass != SM_PC_EDGE)
   4. CrvClassification EndPt Classifies to an Edge (m_vEndPt->PointClass == SM_PC_EDGE)
       but EndInterval attaches to Edge's side not in a Loopuse attached to CrvClassification's Face.

When NULL is returned and EndPt attaches to an Edge (m_vEndPt->PointClass == SM_PC_EDGE) 
the CrvClassification's EndPtClassification is a False positive.  The CurveOnClassify() 
method found that the EndPt intersects an edge (typically a Seam) but didn't check for
the case of a ClassifyCrv on a Face that the Interval is attached to the Side of the Edge
being used in a FaceLoop.  Perhaps in the future this check should be added to
CurveOnClassify() once this method is extended to handle ClassifyCrvs coincident with
the EndPt->EdgeObj.
*************************************************************************/
SmEdgeuse * SmCurveInterval::GetIvlBound_EdgeuseObj
  (SmBoolean     bDoMin,         // in : TRUE = Find Edgeuse Bounding m_vStart side of ClassifyIvl
                                 //      FALSE= Find Edgeuse Bounding m_vEnd side of ClassifyIvl
   SmFaceProps * pOptFaceProps)  // in : For Debug only, NULL to ignore, default:[NULL]
 const
{
  // output
  SmEdgeuse *pBndingEdgeuse = NULL ;

  // locals                    
  SmCurveClassification       * pCrvClassification = GetCurveClassification() ;
  const SmPointClassification * pTgtPtClassify     = bDoMin ? &m_vStart : &m_vEnd ;
  const SmCurve               * pClassifyCrv       = pCrvClassification->GetCurve() ;
  SmEdge                      * pTgtEdgeObj        = pTgtPtClassify->GetEdgeObject() ;
  const SmFace                * pClassifyFace      = pCrvClassification->GetFace() ;
  SmFaceuse                   * pUpperFaceuse      = pClassifyFace->GetUpwardFaceuse() ;
  const SmSurface             * pClassifySurface   = pClassifyFace->GetSurface() ;
  SmTArray<SmEdgeuse*>          sEdgeuses ;        // edgeuses between TgtEdgeObj and pUpperFaceuse
  SmVector3d                    sTgtEdgePN[2] ;
  SmVector3d                    sClassifyCrvPN[2] ;
  SmVector2d                    sTgtClassifySurfUV ;
  SmVector3d                    sTgtClassifySurfNorm ;

  // no work - not bounded by an Edge on a Face with a Surface
  if(   pTgtEdgeObj      == NULL
     || pClassifyFace    == NULL
     || pClassifySurface == NULL)
    { return(NULL) ; }

  // state check: PtClassifies with EdgeObjs must have SM_PC_EDGE classifications
  SM_ASSERT_MSG(pTgtPtClassify->GetPointClass() == SM_PC_EDGE,
                 _T("SmCurveInterval::GetIvlBound_EdgeuseObj(): found an SmPointClassification::m_pObject that's an EdgeObj while SmPointClassification::m_ePointClass != SM_PC_EDGE  - this is a bug.")) ;

  // Get TgtEdgeObj Edgeuses connected to CrvClassification->Face->UpperFaceuse
  pTgtEdgeObj->GetEdgeuses(sEdgeuses, NULL, pUpperFaceuse) ;
  ULONG lEdgeuseCnt = sEdgeuses.GetSize() ;

  // There should only be 1 or 2 upperEdgeuses connected to rCrvClassificaton->Face
  SM_ASSERT_MSG(lEdgeuseCnt == 1 || lEdgeuseCnt == 2,
                _T("SmCurveInterval::GetMinEdgeuse(): PtClassify_EdgeObj doesn't connect to ClassifyFace just once or twice - needs debug")) ;

  // ObjCrv Pt/1stDer at ObjCrv/ClassifyCrv XSect
  SmCurve * pTgtObjectCrv        = pTgtPtClassify->GetCurveObject() ; // EdgeObjCrv
  double    dTgtObjectCrvParam   = pTgtPtClassify->GetTParam() ;      // EdgeObjCrv/ClassifyCrv XSect EdgeObjPt Param
  pTgtObjectCrv->Evaluate(dTgtObjectCrvParam, 1, TRUE, sTgtEdgePN) ;  // EdgeObj XSect Pt/1stDir

  // ClassifyCrv Pt/1stDer at ObjCrv/ClassifyCrv XSect
  double    dTgtClassifyCrvParam = bDoMin ? ( *pCrvClassification ).GetInterval().GetMin() : 
                                            ( *pCrvClassification ).GetInterval().GetMax(); // EdgeObjCrv/ClassifyCrv XSect ClassifyCrvPt Param
  pClassifyCrv->Evaluate(dTgtClassifyCrvParam, 1, TRUE, sClassifyCrvPN) ;          // ClassifyCrv XSect Pt/1stDir

  // CrvClassification Face locals
  bDoMin ? GetMinUV( sTgtClassifySurfUV ) : GetMaxUV( sTgtClassifySurfUV );        // Drop ClassifyCrvPt to FaceSurface
  pClassifySurface->EvaluateNormal(sTgtClassifySurfUV, TRUE, TRUE, sTgtClassifySurfNorm) ; 

  // Find the Edgeuse direction that bounds the ClassifyCrv

   // Sign(TripleProduct(SrfNrm, SeamEdge1stDir, ClassCrv1stDir)): 
   //       Pos = MinIntervalPt ? EdgeuseSAME     Bnds ClassifyIvl : EdgeuseOPPOSITE Bnds ClassifyIvl 
   //       Neg = MinIntervalPt ? EdgeuseOPPOSITE Bnds ClassifyIvl : EdgeuseSAME     Bnds ClassifyIvl
   double            dTgtTripleProduct = sTgtClassifySurfNorm.TripleProduct(sTgtEdgePN[1], sClassifyCrvPN[1]) ;
   SmOrientType eTgtEdgeuseOrient = (dTgtTripleProduct > 0.0) ? (bDoMin ? SM_OT_SAME : SM_OT_OPPOSITE)
                                                              : (bDoMin ? SM_OT_OPPOSITE : SM_OT_SAME) ; 

   // get IvlBounding Edgeuse from desired Edgeuse orientation
   pBndingEdgeuse =   ((lEdgeuseCnt > 0) && (sEdgeuses[0]->GetOrientation() == eTgtEdgeuseOrient)) ? sEdgeuses[0]
                    : ((lEdgeuseCnt > 1) && (sEdgeuses[1]->GetOrientation() == eTgtEdgeuseOrient)) ? sEdgeuses[1]
                    : NULL ;
                  
#ifdef SM_DEBUG_CODE
  SmBoolean bDebugMe = FALSE ;
  if(bDebugMe)
    {
      SmBrep * pBrep = pOptFaceProps->m_pFace ? pOptFaceProps->m_pFace->GetBrep() : NULL ; 

      pOptFaceProps->Dump() ;
      pCrvClassification->Dump() ;

      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(3,4, 1,0,0) ; (*pCrvClassification).Draw(FALSE) ; sm_GraphicsLoop() ;  
      smgfx_SetLook(5,6, 1,.5,0) ; if(pBndingEdgeuse) pBndingEdgeuse->Draw() ; sm_GraphicsLoop() ;
      pOptFaceProps->Draw(TRUE) ; sm_GraphicsLoop() ; // sSheetColor         - def:[ 0, 1, 1]
                                                      // sCrossedSeamColor   - def:[ 1, 0, 1]
                                                      // sMissingSeamColor   - def:[ 1, 0, 0]
                                                      // sMissingPoleColor   - def:[ 0, 0, 1]
                                                      // sBadOrientLoopColor - def:[.3,.3,.3]
                                                      // sNoArea_LoopColor   - def:[ 0, 0, 0]
      sm_GraphicsLoop() ;
    }
#else
   SM_REF1(pOptFaceProps);
#endif // SM_DEBUG_CODE

  // all done
  return(pBndingEdgeuse) ;

} // end SmCurveInterval::GetIvlBound_EdgeuseObj

/*******************************************************************//****
PURPOSE: Return the chord length of a CurveInterval: distance between Ivl end points.

NOTES: Always check the return status.  This will return SM_ERR if
  either end point is UNKNOWN, which is not uncommon.
*************************************************************************/
SmStatus SmCurveInterval::Length3d
  ( double & rdLength )            // out
  const
{
  // Init
  rdLength = -1.0; // error return

  SmPoint3d sPt1, sPt2;

  // Note: don't SER, these need not raise complaints.
  SmStatus eStat = m_vStart.FindObjPoint3d( sPt1 );
  if ( eStat != SM_SUCCESS ) { return eStat; }

  eStat = m_vEnd.FindObjPoint3d( sPt2 );
  if ( eStat != SM_SUCCESS ) { return eStat; }

  rdLength = sPt1.DistanceBetween( sPt2 );

  return SM_SUCCESS;

} // end SmCurveInterval::Length3d()

/*******************************************************************//**
PURPOSE: AssertValid() Test reporting static labels
***********************************************************************/
SmAssertReportLabel sAssertCurveInterval_list[] =
{
  /*  0 */ {SM_AT_POINTER, _T("Bad CurveClass BackPtr"),   _T("m_pCurveClassification back pointer must be nonNULL") },
} ;    

/*******************************************************************//**
PURPOSE:

RETURNS ---  TRUE  = OK
             FALSE = Problem
**********************************************************************/
SmBoolean SmCurveInterval::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL]
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests,
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests
                                    //      default:[SM_LEVEL_0]
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK]
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
  // init rtn value
  SmBoolean bRtn  = TRUE ;

  // Check 0 - m_pCurveClassification back pointer exists
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (m_pCurveClassification != NULL), _T("") ) ;

  // Check contained PointClassifications
  {
    bRtn &= m_vStart.AssertValid(pAList, eTestLevel, eWalkTree, pTestRequests) ; 
    bRtn &= m_vMid.  AssertValid(pAList, eTestLevel, eWalkTree, pTestRequests) ; 
    bRtn &= m_vEnd.  AssertValid(pAList, eTestLevel, eWalkTree, pTestRequests) ; 
  }

  // all done
  // SM_ASSERT(bRtn) ;
  return(bRtn) ;

} // end SmCurveInterval::AssertValid

