/*******************************************************************//****
PURPOSE: Pretty Print

NOTES:
*************************************************************************/
void SmCurveInterval::Dump() const   
{
  SmPoint3d sStartPoint, sEndPoint ;
  const SmCurve * pSrcCurve = m_pCurveClassification ? m_pCurveClassification->GetCurve() : NULL ;
  if(pSrcCurve)
    { pSrcCurve->EvaluatePoint(m_vInterval.GetMin(), sStartPoint) ;
      pSrcCurve->EvaluatePoint(m_vInterval.GetMax(), sEndPoint) ;
    
      // pass the call along
      Dump(pSrcCurve->GetDim(), &sStartPoint, &sEndPoint, m_pCurveClassification->GetSurface1(), m_pCurveClassification->GetSurface2()) ; 
    }
  else
    {
      smos_WriteBuffer(_T("SmCurveInterval Not Initialized\n"));
    }

} // end SmCurveInterval::Dump

/*******************************************************************//****
PURPOSE: Pretty Print

NOTES:
*************************************************************************/
void SmCurveInterval::Dump
  (ULONG            lCurveDim,          // in : Classification Curve dimension, 2 or 3
   const SmPoint3d *pStartPoint,        // in : Interval Start Point
   const SmPoint3d *pEndPoint,          // in : Interval End Point
   const SmSurface *pSurface1,          // in : 1st Surf of surf/surf xSect when Classification curve is an intersection curve
   const SmSurface *pSurface2) const    // in : 2nd Surf of surf/surf xSect when Classification curve is an intersection curve
                                        //      NULL when lCurveDim == 2
{
  SM_ASSERT(lCurveDim == 2 || lCurveDim == 3) ;
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE] ;
  smos_sprintf(sBuff,        _T("%sCurve Interval [%16.16lf, %16.16lf] of CurveClassification [0x%p]\n"),
             lCurveDim == 2 ? _T("UV") : _T("3d"),
             m_vInterval.GetMin(),
             m_vInterval.GetMax(),
             m_pCurveClassification);
  smos_sprintf(sBuffForFile, _T("%sCurve Interval [%16.16lf, %16.16lf] of CurveClassification [%s]\n"),
             lCurveDim == 2 ? _T("UV") : _T("3d"),
             m_vInterval.GetMin(),
             m_vInterval.GetMax(),
             m_pCurveClassification ? _T("NotNULL") : _T("NULL"));
  smos_WriteBuffer(sBuff, sBuffForFile);

  m_vStart.Dump(lCurveDim, m_vInterval.GetMin(), pStartPoint, pSurface1, pSurface2);
  m_vMid.Dump  (lCurveDim);
  m_vEnd.Dump  (lCurveDim, m_vInterval.GetMax(), pEndPoint, pSurface1, pSurface2);

} // end SmCurveInterval::Dump

/*******************************************************************//****
PURPOSE: Draw edges and vertices to which begin/mid/end interval parts
            are classified.

NOTES:
*************************************************************************/
SmDisplayList * SmCurveInterval::Draw() const
{
  SmDisplayList *pRtn = NULL ;

#ifdef SM_GFX_CODE
  // locals
  const SmCurve *cpCurve = m_pCurveClassification ? m_pCurveClassification->GetCurve() : NULL ;

  // start or continue using currently open display list
  smgfx_Open(smgfx_GetRuleColor());

  // draw classification points and their associated object
  m_vStart.Draw();
  m_vMid.Draw() ;
  m_vEnd.Draw() ;

  if(cpCurve && cpCurve->GetDim() != 2)
    { cpCurve->Draw(&m_vInterval) ; }

  pRtn = smgfx_Close() ;

#endif // SM_GFX_CODE
  return(pRtn) ;

} // end SmCurveInterval::Draw

